    int a_a1 = a_gin[1];
    int a_a2 = a_gin[2];
    int a_a3 = a_gin[3];
    int a_a4 = a_gin[4];
    int a_a5 = a_gin[5];
    int a_a6 = a_gin[6];
    int a_a7 = a_gin[7];
    const int* b_data = (const int*)(out + 64);
    volatile int* b_gin = (volatile int*)out;
    int b_a0 = b_gin[0];
    int b_a1 = b_gin[1];
    int b_a2 = b_gin[2];
    int b_a3 = b_gin[3];
    int b_a4 = b_gin[4];
    int b_a5 = b_gin[5];
    int b_a6 = b_gin[6];
    int b_a7 = b_gin[7];
    long long t0 = asm_clock64();
    for (int _i = 0; _i < REPS; _i++) {
        asm volatile(
            "{ .reg .s32 _lt; .reg .s32 _gt;\n\t"
            "ld.volatile.shared.b32 _lt, [%16+0]; xor.b32 %0, %0, _lt;\n\t"
            "ld.global.b32 _gt, [%17+0]; xor.b32 %8, %8, _gt;\n\t"
            "ld.volatile.shared.b32 _lt, [%16+128]; xor.b32 %1, %1, _lt;\n\t"
            "ld.global.b32 _gt, [%17+4]; xor.b32 %9, %9, _gt;\n\t"
            "ld.volatile.shared.b32 _lt, [%16+256]; xor.b32 %2, %2, _lt;\n\t"
            "ld.global.b32 _gt, [%17+8]; xor.b32 %10, %10, _gt;\n\t"
            "ld.volatile.shared.b32 _lt, [%16+384]; xor.b32 %3, %3, _lt;\n\t"
            "ld.global.b32 _gt, [%17+12]; xor.b32 %11, %11, _gt;\n\t"
            "ld.volatile.shared.b32 _lt, [%16+512]; xor.b32 %4, %4, _lt;\n\t"
            "ld.global.b32 _gt, [%17+16]; xor.b32 %12, %12, _gt;\n\t"
            "ld.volatile.shared.b32 _lt, [%16+640]; xor.b32 %5, %5, _lt;\n\t"
            "ld.global.b32 _gt, [%17+20]; xor.b32 %13, %13, _gt;\n\t"
            "ld.volatile.shared.b32 _lt, [%16+768]; xor.b32 %6, %6, _lt;\n\t"
            "ld.global.b32 _gt, [%17+24]; xor.b32 %14, %14, _gt;\n\t"
            "ld.volatile.shared.b32 _lt, [%16+896]; xor.b32 %7, %7, _lt;\n\t"
            "ld.global.b32 _gt, [%17+28]; xor.b32 %15, %15, _gt;\n\t"
            "}\n\t"
            : "+r"(a_a0), "+r"(a_a1), "+r"(a_a2), "+r"(a_a3), "+r"(a_a4), "+r"(a_a5), "+r"(a_a6), "+r"(a_a7), "+r"(b_a0), "+r"(b_a1), "+r"(b_a2), "+r"(b_a3), "+r"(b_a4), "+r"(b_a5), "+r"(b_a6), "+r"(b_a7)
            : "r"(a_addr), "l"(b_data)
        );
    }
    long long t1 = asm_clock64();
    out[2 + threadIdx.x] = a_a0 + a_a1 + a_a2 + a_a3 + a_a4 + a_a5 + a_a6 + a_a7;
    out[34 + threadIdx.x] = b_a0 + b_a1 + b_a2 + b_a3 + b_a4 + b_a5 + b_a6 + b_a7;
    if (threadIdx.x == 0) out[0] = t1 - t0;
}


